# config.toml — McpServerConfig 配置
# config/src/mcp_types.rs:60

[mcp_servers.filesystem]
command = "npx"
args    = ["-y", "@modelcontextprotocol/server-filesystem", "/workspace"]
env     = { }
startup_timeout_sec = 30
tool_timeout_sec    = 120
required            = false
enabled_tools       = ["read_file", "list_directory", "write_file"]

# McpServerTransportConfig::Stdio {
#   command, args, env, env_vars, cwd
# }
# 另一种：McpServerTransportConfig::StreamableHttp {
#   url, bearer_token_env_var, http_headers
# }

// McpConnectionManager::new() — mcp_connection_manager.rs:703
// 对每个 enabled server 创建 AsyncManagedClient（懒初始化）

send_startup_event(McpStartupStatus::Starting { server_name: "filesystem" });

// Stdio 分支 → spawn 子进程
let mut cmd = Command::new("npx");
cmd.kill_on_drop(true)
   .stdin(Stdio::piped())
   .stdout(Stdio::piped())
   .env_clear()              // ← 安全关键：清空父进程环境
   .envs(&resolved_env)
   .args(["-y", "@mcp/server-filesystem", "/workspace"]);

#[cfg(unix)]
cmd.process_group(0);        // 新进程组，SIGTERM 级联

// ProcessGroupGuard::Drop：SIGTERM → 等 2s → SIGKILL

// initialize 握手 — mcp_connection_manager.rs:1384
// 协议版本：ProtocolVersion::V_2025_06_18

client.initialize(InitializeRequestParams {
    protocol_version: ProtocolVersion::V_2025_06_18,
    capabilities: ClientCapabilities {
        elicitation: Some(ElicitationCapability { .. }),
    },
    client_info: Implementation {
        name:    "codex-mcp-client",
        version: env!("CARGO_PKG_VERSION"),
        title:   Some("Codex"),
    },
    meta: None,
}, startup_timeout).await?;

// 检测 server 是否支持沙箱状态扩展：
let supports_sandbox_meta = result.capabilities
    .experimental
    .and_then(|e| e.get("codex/sandbox-state-meta"))
    .is_some();

// 握手完成后立即 list_tools() 并缓存结果

// qualify_tools() — mcp_tool_names.rs:111
// 工具命名：mcp__{server}__{tool}，最长 64 字符

// 字符过滤：[a-zA-Z0-9_] 合法，其余 → "_"
// server="filesystem" tool="read_file"
//   → "mcp__filesystem__read_file"  ✓

// 冲突解决（两个 server 生成相同名）：
// → 附加 SHA-1(server+tool) 前 12 字节 hex
// → "mcp__s__tool_a1b2c3d4e5f6"

// 结果注册：
// HashMap<"mcp__filesystem__read_file", ToolInfo {
//   server_name:      "filesystem",
//   callable_name:    "read_file",
//   callable_namespace: "mcp__filesystem__",
//   tool: Tool { input_schema: { ... } },
//   connector_id: None,
// }>

// 暴露策略 (mcp_tool_exposure.rs):
// 工具总数 < 100 → 全部直接暴露
// 工具总数 ≥ 100 → 仅暴露 explicitly enabled connectors 的工具

// handle_mcp_tool_call() — core/src/mcp_tool_call.rs:74

// Step 1: 查询 ToolAnnotations
// filesystem::read_file 的 annotations:
//   read_only_hint = true    ← 只读，无需审批
//   open_world_hint = false  ← 封闭世界

// Step 2: 审批决策 requires_mcp_tool_approval()
// read_only_hint == true → false（不需要审批）

// Step 3: 沙箱状态注入（server 支持 sandbox-state-meta）
meta["codex/sandbox-state-meta"] = SandboxState {
    sandbox_policy:      SandboxPolicy::WorkspaceWrite { .. },
    sandbox_cwd:         "/workspace",
    use_legacy_landlock: false,
    codex_linux_sandbox_exe: None,
};

// Step 4: 发送 JSON-RPC tools/call
// RmcpClient::call_tool("read_file",
//   args={"path":"/workspace/src/main.rs"},
//   meta=sandbox_state, timeout=120s)

// CallToolResult — protocol/src/mcp.rs:138
{
  "content": [
    {
      "type": "text",
      "text": "fn main() {\n    println!(\"Hello, world!\");\n}"
    }
  ],
  "isError": false
}
